begin;
do $$
declare uid uuid; pid uuid; cid uuid; c public.input_catalog; b1 uuid; b2 uuid; req uuid; ri uuid; q1 uuid; q2 uuid; rid uuid; oid uuid; li uuid; manual uuid; payload jsonb; bp jsonb; before_count integer; who public.profiles; result jsonb;
begin
 select id,company_id into uid,cid from public.profiles where role='MASTER' and active limit 1;
 perform set_config('request.jwt.claim.sub',uid::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 select id into pid from public.projects where company_id=cid limit 1;
 select * into c from public.input_catalog where catalog_active and input_type='MATERIAL' limit 1;
 bp:=jsonb_build_object('title','TESTE TRACE ROLLBACK','baseDate','2026-11-07','bdiConfig','{"ac":5.29,"sg":0.25,"r":1,"df":1.01,"l":8,"cp":3.65,"issBase":60,"issRate":5}'::jsonb,'items',jsonb_build_array(jsonb_build_object('inputId',c.id,'code',c.catalog_code,'unit',c.unit,'source','shared','quantity',2,'unitPrice',10)));
 execute 'set local role authenticated';
 b1:=public.save_budget_version(pid,bp);perform public.set_budget_baseline(pid,b1);
 req:=(public.procurement_action('REQUEST',pid,jsonb_build_object('clientRequestId',gen_random_uuid(),'inputId',c.id,'source','shared','material','nome adulterado','quantity',2,'unit',c.unit,'neededAt',(current_date+5)::text,'justification','Reposição da obra de teste')) ->>'id')::uuid;
 execute 'reset role';
 select id into ri from public.material_request_items where request_id=req;
 if not exists(select 1 from public.material_request_items where id=ri and catalog_input_id=c.id and material_name=c.description) then raise exception 'Request canonical identity missing'; end if;
 payload:=jsonb_build_object('requestId',req,'roundTitle','TESTE TRACE','title','Proposta A','supplierName','TRACE A '||gen_random_uuid(),'validUntil',(current_date+7)::text,'expectedAt',(current_date+3)::text,'items',jsonb_build_array(jsonb_build_object('requestItemId',ri,'inputId',c.id,'source','shared','code',c.catalog_code,'unit',c.unit,'quantity',2,'unitPrice',12)));
 execute 'set local role authenticated';
 q1:=public.save_comparable_quote(pid,payload);
 execute 'reset role';
 select round_id into rid from public.quotations where id=q1;
 if not exists(select 1 from public.quote_rounds where id=rid and request_id=req and budget_id=b1 and trace_version=1) then raise exception 'Round origin absent'; end if;
 if not exists(select 1 from public.material_requests where id=req and status='QUOTING') then raise exception 'Request not quoting'; end if;
 select count(*) into before_count from public.quotations;
 begin perform public.save_comparable_quote(pid,payload||jsonb_build_object('supplierName','TRACE duplicate'));raise exception 'ASSERT duplicate request round';exception when others then if sqlerrm='ASSERT duplicate request round' then raise; end if; end;
 begin perform public.save_comparable_quote(pid,jsonb_set(payload||jsonb_build_object('roundId',rid,'supplierName','TRACE bad qty'),'{items,0,quantity}','3'));raise exception 'ASSERT different qty';exception when others then if sqlerrm='ASSERT different qty' then raise; end if; end;
 begin perform public.save_comparable_quote(pid,payload||jsonb_build_object('roundId',rid,'supplierName','TRACE bad source','requestId',gen_random_uuid()));raise exception 'ASSERT replaced request';exception when others then if sqlerrm='ASSERT replaced request' then raise; end if; end;
 if (select count(*) from public.quotations)<>before_count then raise exception 'Failed quote not atomic'; end if;
 execute 'set local role authenticated';
 b2:=public.save_budget_version(pid,jsonb_set(bp||jsonb_build_object('revisionOf',b1,'revisionReason','Nova previsão de preço'),'{items,0,unitPrice}','20'));perform public.set_budget_baseline(pid,b2);
 q2:=public.save_comparable_quote(pid,payload||jsonb_build_object('roundId',rid,'supplierName','TRACE B '||gen_random_uuid()));
 oid:=public.award_quote(q2,'Fornecedor com entrega adequada');
 if public.award_quote(q2,'Repetir sem duplicar compra')<>oid then raise exception 'Idempotent award failed'; end if;
 execute 'reset role';
 if not exists(select 1 from public.purchase_orders where id=oid and request_id=req and budget_id=b1 and origin_snapshot->'budget'->>'id'=b1::text) then raise exception 'Budget changed retroactively'; end if;
 select id into li from public.purchase_order_items where order_id=oid;
 if not exists(select 1 from public.purchase_order_items where id=li and request_item_id=ri and quotation_item_id is not null and budget_item_id is not null and (budget_refs->0->>'unitPrice')::numeric=10) then raise exception 'Line trace absent'; end if;
 if not exists(select 1 from public.material_requests where id=req and status='ORDERED') then raise exception 'Request not ordered'; end if;
 begin update public.purchase_orders set budget_id=b2 where id=oid;raise exception 'ASSERT mutable origin';exception when others then if sqlerrm='ASSERT mutable origin' then raise; end if; end;
 begin update public.purchase_order_items set budget_refs='[]' where id=li;raise exception 'ASSERT mutable line';exception when others then if sqlerrm='ASSERT mutable line' then raise; end if; end;
 execute 'set local role authenticated';
 perform public.procurement_action('PURCHASE',pid,jsonb_build_object('id',oid));
 perform public.procurement_action('RECEIVE',pid,jsonb_build_object('orderId',oid,'reference','Trace receipt','items',jsonb_build_array(jsonb_build_object('id',li,'quantity',1))));
 manual:=(public.procurement_action('ORDER',pid,jsonb_build_object('supplier','TRACE manual '||gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('code',c.catalog_code,'source','shared','unit',c.unit,'quantity',1,'unitPrice',15))))->>'id')::uuid;
 result:=public.procurement_origins(pid);
 execute 'reset role';
 if not exists(select 1 from public.material_requests where id=req and status='PARTIALLY_RECEIVED') then raise exception 'Partial receipt not propagated'; end if;
 if not exists(select 1 from public.purchase_orders where id=manual and budget_id=b2 and request_id is null) then raise exception 'Manual order did not capture new base'; end if;
 if not exists(select 1 from public.purchase_order_items where order_id=manual and (budget_refs->0->>'unitPrice')::numeric=20) then raise exception 'Manual order line base incorrect'; end if;
 if not exists(select 1 from jsonb_array_elements(result->'requests') r where r->>'id'=req::text and r->'round'->>'id'=rid::text) then raise exception 'Origin selector incomplete'; end if;
 if has_table_privilege('authenticated','public.material_request_items','UPDATE') then raise exception 'Request mutation exposed'; end if;
 for who in select * from public.profiles where company_id=cid and active and role in ('REQUESTER','CLIENT') loop
  perform set_config('request.jwt.claim.sub',who.id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',who.id,'role','authenticated')::text,true);
  execute 'set local role authenticated';
  begin perform public.procurement_origins(pid);raise exception 'ASSERT unauthorized origins';exception when others then if sqlerrm='ASSERT unauthorized origins' then raise; end if; end;
  begin perform public.prepare_quote_origin(rid,pid,payload);raise exception 'ASSERT exposed helper';exception when others then if sqlerrm='ASSERT exposed helper' then raise; end if; end;
  execute 'reset role';
 end loop;
end $$;
rollback;
